<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import AdminConfirmDialog from '@/Components/Admin/AdminConfirmDialog.vue';
import AdminDataCard from '@/Components/Admin/AdminDataCard.vue';
import AdminPageHeader from '@/Components/Admin/AdminPageHeader.vue';
import AdminPagination from '@/Components/Admin/AdminPagination.vue';
import AdminStatusBadge from '@/Components/Admin/AdminStatusBadge.vue';
import AdminTable from '@/Components/Admin/AdminTable.vue';
import AdminTextInput from '@/Components/Admin/AdminTextInput.vue';
import AdminTextarea from '@/Components/Admin/AdminTextarea.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { ref, watch } from 'vue';

const props = defineProps({ page: { type: Object, required: true } }); const module = props.page.module; const search = ref(module.filters.search || ''); const effectiveStatus = ref(module.filters.effective_status || ''); const mode = ref(module.filters.mode || ''); const expiring = ref(module.filters.expiring_within || ''); const voiding = ref(null); const voidForm = useForm({ version: '', reason: '' }); let timer;
watch([search, effectiveStatus, mode, expiring], () => { clearTimeout(timer); timer = setTimeout(() => router.get(route('admin.warranties.index'), { search: search.value || undefined, effective_status: effectiveStatus.value || undefined, mode: mode.value || undefined, expiring_within: expiring.value || undefined }, { preserveState: true, replace: true }), 250); });
const askVoid = (warranty) => { voiding.value = warranty; voidForm.version = warranty.version; voidForm.reason = ''; }; const submitVoid = () => voidForm.patch(route('admin.warranties.void', voiding.value.id), { preserveScroll: true, onFinish: () => { voiding.value = null; } });
</script>

<template><Head :title="page.meta.title" /><AuthenticatedLayout><AdminPageHeader :title="page.meta.title" description="Theo dõi bảo hành theo đơn hàng hoặc đăng ký thủ công"><Link :href="route('admin.warranties.create')" class="rounded-lg bg-admin-accent px-4 py-2 text-sm font-semibold text-admin-page">Tạo bảo hành</Link></AdminPageHeader><AdminDataCard title="Bộ lọc bảo hành" class="mt-6"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><AdminTextInput v-model="search" placeholder="Serial, sản phẩm, khách hàng" aria-label="Tìm bảo hành" /><select v-model="effectiveStatus" aria-label="Lọc hiệu lực" class="border border-admin-border bg-admin-page px-3 py-2 text-sm text-admin-content"><option value="">Tất cả hiệu lực</option><option v-for="item in module.statuses" :key="item.key" :value="item.key">{{ item.label }}</option></select><select v-model="mode" aria-label="Lọc nguồn" class="border border-admin-border bg-admin-page px-3 py-2 text-sm text-admin-content"><option value="">Tất cả nguồn</option><option value="order">Theo đơn hàng</option><option value="manual">Thủ công</option></select><select v-model="expiring" aria-label="Lọc sắp hết hạn" class="border border-admin-border bg-admin-page px-3 py-2 text-sm text-admin-content"><option value="">Tất cả thời hạn</option><option value="30">Hết hạn trong 30 ngày</option></select></div></AdminDataCard><AdminDataCard title="Danh sách bảo hành" class="mt-6"><AdminTable :columns="[{ key: 'serial', label: 'Serial' }, { key: 'product', label: 'Sản phẩm' }, { key: 'source', label: 'Nguồn' }, { key: 'customer', label: 'Khách hàng' }, { key: 'expiry', label: 'Hết hạn' }, { key: 'status', label: 'Hiệu lực' }, { key: 'action', label: 'Thao tác' }]" ><tr v-for="warranty in module.items" :key="warranty.id" class="border-b border-admin-border"><td class="px-3 py-3 font-mono text-sm text-admin-content">{{ warranty.serial }}</td><td class="px-3 py-3 text-sm text-admin-content">{{ warranty.product_name }}</td><td class="px-3 py-3 text-sm text-admin-content-muted">{{ warranty.source.label }}<Link v-if="warranty.order" :href="warranty.order.url" class="block text-xs text-admin-accent">{{ warranty.order.order_number }}</Link></td><td class="px-3 py-3 text-sm text-admin-content-muted">{{ warranty.customer.name || 'Chưa cập nhật' }}<span class="block text-xs">{{ warranty.customer.phone_masked || '' }}</span></td><td class="px-3 py-3 text-sm text-admin-content-muted">{{ warranty.expiration_date_display }}</td><td class="px-3 py-3"><AdminStatusBadge :status="{ key: warranty.effective_status, label: warranty.effective_status_label }" /></td><td class="px-3 py-3 text-right"><Link :href="warranty.edit_url" class="mr-3 text-sm text-admin-accent">Sửa</Link><button v-if="warranty.allowed_actions.void" type="button" class="text-sm text-admin-danger" @click="askVoid(warranty)">Hủy</button></td></tr><tr v-if="!module.items.length"><td colspan="7" class="px-3 py-10 text-center text-sm text-admin-content-muted">Chưa có bảo hành phù hợp.</td></tr></AdminTable><AdminPagination class="mt-4" :pagination="module.pagination" /></AdminDataCard><AdminConfirmDialog :open="!!voiding" title="Hủy bảo hành" message="Bảo hành sẽ được giữ lại để bảo toàn lịch sử. Hãy nhập lý do hủy." confirm-label="Hủy bảo hành" danger :processing="voidForm.processing" @cancel="voiding = null" @confirm="submitVoid"><template #default><AdminTextarea v-model="voidForm.reason" rows="3" placeholder="Lý do hủy bắt buộc" /></template></AdminConfirmDialog></AuthenticatedLayout></template>
